import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img, random, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily } = loadFont();



export type InstagramFollowCardProps = Record<string, any>;

// Generate deterministic particles for the click burst effect
const particles = Array.from({ length: 16 }).map((_, i) => {
  const angle = (i / 16) * Math.PI * 2 + (random(`p-angle-${i}`) * 0.4 - 0.2);
  const speed = 5 + random(`p-speed-${i}`) * 6;
  const size = 5 + random(`p-size-${i}`) * 5;
  const color = [
    "#FF3040", // Instagram Pink
    "#FFC107", // Yellow / Gold
    "#00F5FF", // Neon Cyan
    "#0095f6", // IG Blue
    "#bc1888", // Purple
  ][i % 5];
  return { angle, speed, size, color };
});

const InstagramFollowCard: React.FC<InstagramFollowCardProps> = ({
  backgroundColor = "#0b0b0e",
  transparentBackground = false,
  durationInSeconds = 5,
  theme = "dark",
  scale = 1,
  cardWidth = 440,
  cardHeight = 560,
  username = "@malloy",
  fullName = "Malloy AI",
  bioText = "Next-generation intelligent code engine. Crafting high-fidelity components and motion systems with flawless execution.",
  postsCount = 124,
  followersCount = "1.5M",
  followingCount = "290",
  avatarUrl = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=200&h=200&fit=crop",
  buttonColor = "#0095f6",
  followingButtonColor = "#363636",
  storyActive = true,
  fullNameFontSize = 24,
  usernameFontSize = 15,
  statsFontSize = 16,
  statsLabelFontSize = 12,
  bioFontSize = 14,
  buttonFontSize = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Theme styles resolution
  const isDark = theme === "dark";
  const cardBg = isDark ? "rgba(20, 20, 23, 0.85)" : "rgba(255, 255, 255, 0.9)";
  const cardBorder = isDark ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)";
  const textColor = isDark ? "#ffffff" : "#0f1419";
  const secondaryTextColor = isDark ? "#a1a1aa" : "#536471";
  const actualFollowingBtnColor = isDark ? followingButtonColor : "#efefef";
  const followingTextColor = isDark ? "#ffffff" : "#0f1419";
  const cardShadow = isDark ? "0px 30px 80px rgba(0, 0, 0, 0.6)" : "0px 30px 80px rgba(0, 0, 0, 0.08)";

  // Background Ambient Blob Animations
  const blob1X = interpolate(Math.sin(frame * 0.015), [-1, 1], [width * 0.25, width * 0.45]);
  const blob1Y = interpolate(Math.cos(frame * 0.02), [-1, 1], [height * 0.25, height * 0.55]);
  const blob2X = interpolate(Math.cos(frame * 0.018), [-1, 1], [width * 0.55, width * 0.75]);
  const blob2Y = interpolate(Math.sin(frame * 0.022), [-1, 1], [height * 0.45, height * 0.75]);

  // Card Entrance Springs
  const cardEntranceSpring = spring({
    frame: frame - 5,
    fps,
    config: { damping: 15, mass: 0.8, stiffness: 100 },
  });
  const cardScale = interpolate(cardEntranceSpring, [0, 1], [0.8, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  }) * scale;
  const cardOpacity = interpolate(cardEntranceSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const cardTranslateY = interpolate(cardEntranceSpring, [0, 1], [60, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Avatar Entrance Spring
  const avatarEntranceSpring = spring({
    frame: frame - 12,
    fps,
    config: { damping: 12, mass: 0.6, stiffness: 130 },
  });
  const avatarScale = interpolate(avatarEntranceSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Text / Content Fade and Rise
  const contentFade = interpolate(frame, [18, 32], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const contentTranslateY = interpolate(frame, [18, 32], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Story Ring Spin Rotation
  const storySpin = interpolate(frame, [0, 300], [0, 360]);

  // Follow Button Entrance Spring
  const buttonEntranceSpring = spring({
    frame: frame - 22,
    fps,
    config: { damping: 14, mass: 0.7, stiffness: 110 },
  });
  const buttonEntranceScale = interpolate(buttonEntranceSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- BUTTON INTERACTION TIMELINE ---
  // Taps down and switch states at frame 75
  const clickStartFrame = 75;

  // 1. Button Press Down & Squash
  const buttonTapScale = interpolate(
    frame,
    [clickStartFrame, clickStartFrame + 5, clickStartFrame + 12],
    [1, 0.88, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 2. Button State Morphing (Follow -> Following)
  const morphSpring = spring({
    frame: frame - (clickStartFrame + 5),
    fps,
    config: { damping: 16, mass: 0.5, stiffness: 140 },
  }); // ranges smoothly from 0 to 1

  // Color transition for button
  const currentButtonBg = interpolate(
    morphSpring,
    [0, 1],
    [0, 1]
  ); // We will manually mix colors using linear gradient or styles

  // Transition texts with sliding motion
  const followTextY = interpolate(morphSpring, [0, 1], [0, -25], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const followTextOpacity = interpolate(morphSpring, [0, 0.8], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const followingTextY = interpolate(morphSpring, [0, 1], [25, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const followingTextOpacity = interpolate(morphSpring, [0.2, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Burst Particles Calculation
  const burstFrame = frame - clickStartFrame;
  const showBurst = burstFrame >= 0 && burstFrame < 30;

  // Metallic Shine Sweep
  const shineTranslateX = interpolate(frame, [15, 65], [-cardWidth, cardWidth], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Decorative Ambient Background Blobs */}
      {!transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              left: blob1X,
              top: blob1Y,
              width: 500,
              height: 500,
              borderRadius: "50%",
              background: "radial-gradient(circle, rgba(230,104,60,0.18) 0%, rgba(220,39,67,0.1) 50%, rgba(0,0,0,0) 70%)",
              filter: "blur(80px)",
              transform: "translate(-50%, -50%)",
              pointerEvents: "none",
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              left: blob2X,
              top: blob2Y,
              width: 550,
              height: 550,
              borderRadius: "50%",
              background: "radial-gradient(circle, rgba(0,149,246,0.15) 0%, rgba(188,24,136,0.08) 50%, rgba(0,0,0,0) 70%)",
              filter: "blur(90px)",
              transform: "translate(-50%, -50%)",
              pointerEvents: "none",
              transition: "none",
            }}
          />
        </>
      )}

      {/* Main Instagram Follow Card */}
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          background: cardBg,
          border: cardBorder,
          borderRadius: 28,
          boxShadow: cardShadow,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: 36,
          boxSizing: "border-box",
          position: "relative",
          overflow: "hidden",
          backdropFilter: "blur(20px)",
          opacity: cardOpacity,
          transform: `scale(${cardScale}) translateY(${cardTranslateY}px)`,
          transition: "none",
        }}
      >
        {/* Reflection Sweep Overlay */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "200%",
            height: "100%",
            background: "linear-gradient(115deg, transparent 35%, rgba(255, 255, 255, 0.04) 45%, rgba(255, 255, 255, 0.1) 50%, rgba(255, 255, 255, 0.04) 55%, transparent 65%)",
            transform: `translateX(${shineTranslateX}px)`,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Profile Avatar Frame with Active Story Ring */}
        <div
          style={{
            transform: `scale(${avatarScale})`,
            marginTop: 10,
            marginBottom: 20,
            position: "relative",
            width: 124,
            height: 124,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          {storyActive ? (
            <div
              style={{
                position: "absolute",
                width: 124,
                height: 124,
                borderRadius: "50%",
                background: "linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%)",
                transform: `rotate(${storySpin}deg)`,
                transition: "none",
              }}
            />
          ) : (
            <div
              style={{
                position: "absolute",
                width: 124,
                height: 124,
                borderRadius: "50%",
                background: isDark ? "#3a3a3a" : "#dbdbdb",
                transition: "none",
              }}
            />
          )}

          {/* Mask ring creates negative space gap between avatar and story ring */}
          <div
            style={{
              position: "absolute",
              width: 116,
              height: 116,
              borderRadius: "50%",
              backgroundColor: isDark ? "#141417" : "#ffffff",
              transition: "none",
            }}
          />

          {/* Avatar Image */}
          <div
            style={{
              position: "absolute",
              width: 106,
              height: 106,
              borderRadius: "50%",
              overflow: "hidden",
              backgroundColor: isDark ? "#2a2a2a" : "#f0f0f0",
              transition: "none",
            }}
          >
            <Img
              src={avatarUrl}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                transition: "none",
              }}
            />
          </div>
        </div>

        {/* Text and Statistics Group */}
        <div
          style={{
            opacity: contentFade,
            transform: `translateY(${contentTranslateY}px)`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            width: "100%",
            transition: "none",
          }}
        >
          {/* Names */}
          <div style={{ fontWeight: 800, fontSize: fullNameFontSize, color: textColor, marginBottom: 2, transition: "none" }}>
            {fullName}
          </div>
          <div style={{ fontWeight: 500, fontSize: usernameFontSize, color: secondaryTextColor, marginBottom: 20, transition: "none" }}>
            {username}
          </div>

          {/* Instagram Stats Grid */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              width: "85%",
              marginBottom: 20,
              borderTop: isDark ? "1px solid rgba(255,255,255,0.06)" : "1px solid rgba(0,0,0,0.06)",
              borderBottom: isDark ? "1px solid rgba(255,255,255,0.06)" : "1px solid rgba(0,0,0,0.06)",
              paddingTop: 12,
              paddingBottom: 12,
              transition: "none",
            }}
          >
            <div style={{ textAlign: "center", flex: 1, transition: "none" }}>
              <div style={{ fontWeight: 800, fontSize: statsFontSize, color: textColor, transition: "none" }}>
                {postsCount}
              </div>
              <div style={{ fontSize: statsLabelFontSize, color: secondaryTextColor, marginTop: 1, transition: "none" }}>
                Posts
              </div>
            </div>
            <div style={{ textAlign: "center", flex: 1, borderLeft: isDark ? "1px solid rgba(255,255,255,0.06)" : "1px solid rgba(0,0,0,0.06)", borderRight: isDark ? "1px solid rgba(255,255,255,0.06)" : "1px solid rgba(0,0,0,0.06)", transition: "none" }}>
              <div style={{ fontWeight: 800, fontSize: statsFontSize, color: textColor, transition: "none" }}>
                {followersCount}
              </div>
              <div style={{ fontSize: statsLabelFontSize, color: secondaryTextColor, marginTop: 1, transition: "none" }}>
                Followers
              </div>
            </div>
            <div style={{ textAlign: "center", flex: 1, transition: "none" }}>
              <div style={{ fontWeight: 800, fontSize: statsFontSize, color: textColor, transition: "none" }}>
                {followingCount}
              </div>
              <div style={{ fontSize: statsLabelFontSize, color: secondaryTextColor, marginTop: 1, transition: "none" }}>
                Following
              </div>
            </div>
          </div>

          {/* Bio / Description */}
          <div
            style={{
              fontSize: bioFontSize,
              color: secondaryTextColor,
              textAlign: "center",
              lineHeight: 1.5,
              paddingLeft: 10,
              paddingRight: 10,
              marginBottom: 28,
              height: 60,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            {bioText}
          </div>
        </div>

        {/* Action Button Container */}
        <div
          style={{
            width: "100%",
            marginTop: "auto",
            position: "relative",
            display: "flex",
            justifyContent: "center",
            transform: `scale(${buttonEntranceScale})`,
            transition: "none",
          }}
        >
          {/* Burst Particles System */}
          {showBurst &&
            particles.map((p, i) => {
              const distance = interpolate(burstFrame, [0, 24], [0, p.speed * 10], {
                extrapolateRight: "clamp",
                easing: Easing.out(Easing.quad),
              });
              const opacity = interpolate(burstFrame, [0, 16, 24], [0, 1, 0], {
                extrapolateRight: "clamp",
              });
              const scale = interpolate(burstFrame, [0, 4, 24], [0, 1.3, 0], {
                extrapolateRight: "clamp",
              });

              const x = Math.cos(p.angle) * distance;
              const y = Math.sin(p.angle) * distance;

              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    width: p.size,
                    height: p.size,
                    borderRadius: "50%",
                    backgroundColor: p.color,
                    opacity,
                    transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${scale})`,
                    pointerEvents: "none",
                    zIndex: 10,
                    transition: "none",
                  }}
                />
              );
            })}

          {/* Dynamic Follow / Following Button */}
          <button
            style={{
              width: "100%",
              height: 48,
              border: "none",
              borderRadius: 14,
              cursor: "pointer",
              fontWeight: 700,
              fontSize: buttonFontSize,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              position: "relative",
              overflow: "hidden",
              outline: "none",
              backgroundColor: interpolate(currentButtonBg, [0, 1], [0, 1]) === 0 ? buttonColor : "transparent",
              // Inline fallback interpolation styles using variables
              transform: `scale(${buttonTapScale})`,
              boxShadow: isDark
                ? "0 4px 20px rgba(0, 149, 246, 0.15)"
                : "0 4px 20px rgba(0, 0, 0, 0.05)",
              transition: "none",
            }}
          >
            {/* Morphing Background Layer */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: buttonColor,
                opacity: 1 - currentButtonBg,
                transition: "none",
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: actualFollowingBtnColor,
                opacity: currentButtonBg,
                transition: "none",
              }}
            />

            {/* Label State 1: Follow */}
            <div
              style={{
                position: "absolute",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "#ffffff",
                transform: `translateY(${followTextY}px)`,
                opacity: followTextOpacity,
                transition: "none",
              }}
            >
              Follow
            </div>

            {/* Label State 2: Following */}
            <div
              style={{
                position: "absolute",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: followingTextColor,
                transform: `translateY(${followingTextY}px)`,
                opacity: followingTextOpacity,
                transition: "none",
              }}
            >
              {/* Dynamic Animated Checkmark Path */}
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="3.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ marginRight: 6, transition: "none" }}
              >
                <polyline
                  points="20 6 9 17 4 12"
                  style={{
                    strokeDasharray: 30,
                    strokeDashoffset: (1 - morphSpring) * 30,
                    transition: "none",
                  }}
                />
              </svg>
              Following
            </div>
          </button>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InstagramFollowCard;